<template>
 <div id="diary" :class="{'large-text': largeText}">
  <svg class="svg-defs" xmlns="http://www.w3.org/2000/svg"><defs>
   <symbol id="i-home" viewBox="0 0 24 24"><path d="M3 10 12 2l9 8M5 9v12h14V9M9 21v-8h6v8M2 22h20"/></symbol>
   <symbol id="i-book" viewBox="0 0 24 24"><path d="M12 5v16M12 5C8 2 4 3 2 4v15c4-2 7-1 10 2 3-3 6-4 10-2V4c-3-1-7-2-10 1Z"/></symbol>
   <symbol id="i-calendar" viewBox="0 0 24 24"><rect x="3" y="4" width="18" height="17" rx="2"/><path d="M7 2v5m10-5v5M3 10h18m-13 4h1m6 0h1m-8 4h1m6 0h1"/></symbol>
   <symbol id="i-heart" viewBox="0 0 24 24"><path d="M12 21S2 15 2 8a5 5 0 0 1 10-2 5 5 0 0 1 10 2c0 7-10 13-10 13Z"/></symbol>
   <symbol id="i-user" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><circle cx="12" cy="9" r="3"/><path d="M5 19v-2c0-5 14-5 14 0v2"/></symbol>
   <symbol id="i-edit" viewBox="0 0 24 24"><path d="m15 3 6 6M3 21l6-1L22 7l-6-6L3 14v7Z"/></symbol>
   <symbol id="i-arrow" viewBox="0 0 24 24"><path d="M3 12h17m-6-6 6 6-6 6"/></symbol>
   <symbol id="i-settings" viewBox="0 0 24 24"><path d="m9 2-1 3-3 1-3 3 2 3-1 3 3 3 3-1 3 3 3-2 3 1 3-4-2-3 1-3-3-3-3 1-2-3Z"/><circle cx="12" cy="11" r="3"/></symbol>
   <symbol id="i-search" viewBox="0 0 24 24"><circle cx="10" cy="10" r="7"/><path d="m15 15 7 7"/></symbol>
   <symbol id="i-close" viewBox="0 0 24 24"><path d="m5 5 14 14M5 19 19 5"/></symbol>
   <symbol id="i-download" viewBox="0 0 24 24"><path d="M12 2v14m-5-5 5 5 5-5M3 15v6h18v-6"/></symbol>
   <symbol id="i-sun" viewBox="0 0 24 24"><circle cx="12" cy="12" r="4"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/></symbol>
   <symbol id="i-trash" viewBox="0 0 24 24"><path d="M3 5h18M9 5V2h6v3M5 5l1 17h12l1-17M9 9v9m6-9v9"/></symbol>
  </defs></svg>
  <header class="header" v-if="!editor">
   <template v-if="tab==='home'"><div class="brand"><span class="brandmark">N<span>•</span></span>NFTALT</div><button class="icon-button" aria-label="New entry" @click="newEntry"><icon name="edit"/></button><button class="avatar mini" aria-label="Profile" @click="tab='profile'"><img :src="artPath(profile.avatar||'tiger')" alt=""/></button></template>
   <template v-else><button class="icon-button" aria-label="Go home" @click="tab='home'"><icon name="arrow" class="back"/></button><b>{{tabTitle}}</b><button class="icon-button" :aria-label="tab==='profile'?'Settings':'New entry'" @click="tab==='profile'?openSettings():newEntry()"><icon :name="tab==='profile'?'settings':'edit'"/></button></template>
  </header>
  <main v-if="!editor">
   <template v-if="tab==='home'">
    <section class="hero"><div class="eyebrow">{{todayLabel}}</div><h1>Every day,<br>your story<span class="hero-dot">.</span></h1><div class="cover-stack art-stack" @touchstart="heroTouch=$event.changedTouches[0].clientX" @touchend="swipeHero($event)"><button class="cover back-cover left-cover" aria-label="Previous cover" @click="changeHero(-1)"><img :src="artPath(heroPrevious.id)" alt=""/></button><button class="cover back-cover right-cover" aria-label="Next cover" @click="changeHero(1)"><img :src="artPath(heroNext.id)" alt=""/></button><button class="cover main-cover art-cover" @click="newEntry()" aria-label="Write an entry"><img :src="artPath(heroArt.id)" :alt="heroArt.name"/><span class="art-shade"></span><div class="cover-top"><span>YOUR MOMENT COLLECTION</span><icon name="arrow"/></div><div class="cover-title">{{heroArt.name}}</div><div class="cover-bottom"><span>REMEMBER THIS DAY</span><span class="small-mark">N</span></div></button><div class="cover-sticker">N &nbsp; Just for you</div></div><div class="hero-caption"><span>Diary covers <icon name="arrow"/></span><div class="dots"><button v-for="(art,index) in heroArts" :key="art.id" :class="{current:index===heroIndex}" :aria-label="'Cover '+(index+1)" @click="heroIndex=index"></button><small>{{String(heroIndex+1).padStart(2,'0')}} / 03</small></div></div></section>
    <div class="ticker"><span>Your thoughts matter</span><b>N</b><span>One day. One story.</span><b>N</b><span>Be yourself</span></div>
    <section class="quick-card"><button @click="newEntry"><icon name="edit"/><span>Write</span></button><button @click="tab='calendar'"><icon name="calendar"/><span>Calendar</span></button><button @click="tab='favorites'"><icon name="heart"/><span>Favorites</span></button><button @click="tab='entries'"><icon name="book"/><span>All entries</span></button><button @click="moodDialog=true"><icon name="sun"/><span>Mood</span></button><button @click="tab='profile'"><icon name="user"/><span>My profile</span></button></section>
    <div class="privacy-line"><span><i></i> Personal diary</span><span>Saved on your device</span></div>
    <section class="section"><div class="section-heading"><h2>Recent entries</h2><button class="circle-button" @click="tab='entries'" aria-label="All entries"><icon name="arrow"/></button></div><entry-card v-for="entry in latest" :key="entry.id" :entry="entry" @open="openEntry(entry)" @favorite="toggleFavorite(entry)"/><div class="empty" v-if="!entries.length"><icon name="book"/><h3>Your story starts here</h3><p>Save a thought, a little joy or a moment worth remembering.</p><button class="primary" @click="newEntry">Write your first entry <icon name="arrow"/></button></div></section>
   </template>
   <template v-if="tab==='entries'||tab==='favorites'">
    <section class="page-content"><div class="page-intro"><span class="eyebrow">{{tab==='favorites'?'CLOSE TO YOUR HEART':'YOUR PERSONAL COLLECTION'}}</span><h1>{{tab==='favorites'?'Keep it close.':'My stories.'}}</h1><p>{{tab==='favorites'?'Moments you want to return to.':'Big days and little details.'}}</p></div><div class="search"><icon name="search"/><input v-model="search" placeholder="Find an entry" aria-label="Search entries"/></div><div class="filter-row"><button v-for="m in ['All','Happy','Calm','Low']" :key="m" :class="{selected:filterMood===m}" @click="filterMood=m">{{m}}</button></div><div class="count-line">{{visibleEntries.length}} {{recordWord(visibleEntries.length)}}<span>Newest first</span></div><entry-card v-for="entry in visibleEntries" :key="entry.id" :entry="entry" @open="openEntry(entry)" @favorite="toggleFavorite(entry)"/><div v-if="!visibleEntries.length" class="empty"><icon :name="tab==='favorites'?'heart':'book'"/><h3>{{entries.length?'No entries found':'A fresh page awaits'}}</h3><p>{{tab==='favorites'?'Tap the heart on an entry to keep it here.':'Add your first entry or try a different search.'}}</p><button class="primary" @click="newEntry">New entry <icon name="edit"/></button></div></section>
   </template>
   <template v-if="tab==='calendar'"><section class="page-content"><div class="page-intro"><span class="eyebrow">DAY BY DAY</span><h1>Calendar<br>of moments.</h1></div><div class="calendar card"><div class="month-nav"><button class="icon-button" @click="changeMonth(-1)" aria-label="Previous month"><icon name="arrow" class="back"/></button><b>{{monthLabel}}</b><button class="icon-button" @click="changeMonth(1)" aria-label="Next month"><icon name="arrow"/></button></div><div class="calendar-grid"><span class="weekday" v-for="d in ['Mon','Tue','Wed','Thu','Fri','Sat','Sun']" :key="d">{{d}}</span><button v-for="(day,index) in calendarDays" :key="index" :disabled="!day" :class="{chosen:day&&dayKey(day)===selectedDate,today:day&&dayKey(day)===today,hasEntry:day&&hasDay(dayKey(day))}" @click="selectedDate=dayKey(day)">{{day||''}}<i v-if="day&&hasDay(dayKey(day))"></i></button></div></div><div class="section-heading"><h2>{{formatDate(selectedDate)}}</h2><button class="circle-button" @click="newEntry(selectedDate)" aria-label="Write for this date"><icon name="edit"/></button></div><entry-card v-for="entry in dayEntries" :key="entry.id" :entry="entry" @open="openEntry(entry)" @favorite="toggleFavorite(entry)"/><div v-if="!dayEntries.length" class="empty"><p>No entries for this day yet.</p><button class="text-button" @click="newEntry(selectedDate)">Add a memory <icon name="arrow"/></button></div></section></template>
   <template v-if="tab==='profile'"><section class="page-content profile-page"><div class="profile-card card"><div class="profile-top"><button class="avatar big" @click="artworkTarget='avatar';artworkDialog=true" aria-label="Choose an avatar"><img :src="artPath(profile.avatar||'tiger')" alt=""/></button><div><span class="eyebrow">YOUR OWN SPACE</span><h2>{{profile.name||'NFTALT'}}</h2><small>Your story starts here</small></div><button class="edit-profile" @click="nameDraft=profile.name;profileDialog=true" aria-label="Edit your name"><icon name="edit"/></button></div><div class="profile-foot"><span><i></i> Just for you</span><span>Since {{profile.since}}</span></div></div><div class="stat-grid"><button @click="tab='entries'"><icon name="book"/><b>{{entries.length}}</b><small>Entries</small></button><button @click="tab='calendar'"><icon name="calendar"/><b>{{activeDays}}</b><small>Days with entries</small></button><button @click="tab='favorites'"><icon name="heart"/><b>{{favoritesCount}}</b><small>Favorites</small></button></div><div class="group-label">MY DIARY</div><div class="menu-card card"><button @click="tab='entries'"><span class="menu-icon"><icon name="book"/></span><div>All entries<small>Your collection of memories</small></div><icon name="arrow"/></button><button @click="openSettings"><span class="menu-icon"><icon name="settings"/></span><div>Settings<small>Make your diary feel right</small></div><icon name="arrow"/></button><button @click="exportEntries"><span class="menu-icon"><icon name="download"/></span><div>Export entries<small>Save a backup copy</small></div><icon name="arrow"/></button><button @click="importDialog=true"><span class="menu-icon"><icon name="calendar"/></span><div>Import entries<small>Restore from JSON</small></div><icon name="arrow"/></button></div><div class="group-label">ABOUT</div><div class="menu-card card"><button @click="info='privacy'"><span class="menu-icon"><icon name="user"/></span><div>Privacy<small>Where your stories are stored</small></div><icon name="arrow"/></button><button @click="info='about'"><span class="menu-icon"><icon name="book"/></span><div>About the diary<small>A place to be yourself</small></div><icon name="arrow"/></button></div><button class="support-button text-button" @click="openSupport">Support <icon name="arrow"/></button><p class="version">NFTALT · VERSION 1.1.0</p></section></template>
  </main>
  <nav class="tabbar" v-if="!editor" aria-label="Main navigation"><button v-for="item in tabs" :key="item.id" :class="{active:tab===item.id}" @click="switchTab(item.id)"><span><icon :name="item.icon"/></span><small>{{item.label}}</small></button></nav>
  <section class="editor" v-if="editor"><header class="editor-header"><button class="icon-button" @click="closeEditor" aria-label="Close"><icon name="close"/></button><b>{{draft.id?'My entry':'A new story'}}</b><button class="save-button" @click="saveEntry">Done</button></header><div class="editor-content"><div class="editor-meta"><input type="date" v-model="draft.date" aria-label="Entry date"/><button @click="draft.favorite=!draft.favorite" class="icon-button" :class="{coral:draft.favorite}" aria-label="Add to favorites"><icon name="heart"/></button></div><div class="eyebrow">WORDS WORTH KEEPING</div><input class="title-input" v-model="draft.title" placeholder="Name your day" maxlength="120" aria-label="Entry title"/><button class="editor-cover" @click="artworkTarget='entry';artworkDialog=true"><img :src="artPath(draft.artworkId||'copper-muse')" alt="Entry cover"/><span>Entry cover<small>{{artName(draft.artworkId||'copper-muse')}}</small></span><icon name="arrow"/></button><div class="mood-picker"><button v-for="m in moods" :key="m.label" :class="{selected:draft.mood===m.label}" @click="draft.mood=m.label"><span>{{m.face}}</span>{{m.label}}</button></div><textarea ref="bodyInput" v-model="draft.body" placeholder="What would you like to remember today?\n\nHere, you can be yourself." aria-label="Entry text"></textarea><div class="editor-bottom"><span>{{draft.body.length}} characters · {{wordCount}} words</span><button v-if="draft.id" class="text-button danger" @click="deleteDialog=true"><icon name="trash"/> Delete</button></div><p class="local-note">Your entry is saved on this device when you tap Done.</p></div></section>
  <div class="overlay" v-if="moodDialog||profileDialog||settingsDialog||importDialog||artworkDialog||eraseDialog||info||deleteDialog||discardDialog" @click.self="closeDialogs"><section class="dialog"><button class="dialog-close icon-button" @click="closeDialogs" aria-label="Close"><icon name="close"/></button><template v-if="moodDialog"><span class="eyebrow">A MOMENT FOR YOURSELF</span><h2>How are you today?</h2><p>Choose a mood and save a few words about your day.</p><div class="dialog-moods"><button v-for="m in moods" :key="m.label" @click="newMoodEntry(m.label)"><span>{{m.face}}</span>{{m.label}}</button></div></template><template v-if="profileDialog"><span class="eyebrow">MAKE YOURSELF AT HOME</span><h2>What should we call you?</h2><input class="dialog-input" v-model="nameDraft" placeholder="Your name" maxlength="32"/><button class="primary full" @click="saveProfile">Save <icon name="arrow"/></button></template><template v-if="settingsDialog"><span class="eyebrow">YOUR OWN RHYTHM</span><h2>Settings</h2><button class="setting-row" @click="largeText=!largeText;persistPreferences()"><span>Larger text<small>Make your entries easier to read</small></span><span class="switch" :class="{on:largeText}"></span></button><button class="setting-row" @click="settingsDialog=false;nameDraft=profile.name;profileDialog=true"><span>Profile name<small>{{profile.name||'NFTALT'}}</small></span><icon name="arrow"/></button><button class="setting-row danger" @click="settingsDialog=false;eraseDialog=true"><span>Delete all data<small>Entries and settings on this device</small></span><icon name="trash"/></button><p>Your diary works without an account, ads or a server connection.</p></template><template v-if="info"><span class="eyebrow">MY DIARY</span><h2>{{info==='privacy'?'Keep your world personal.':'Collect your own story.'}}</h2><p v-if="info==='privacy'">Your entries and profile name stay on this device. The app does not send them to a server or use analytics. Uninstalling the app or clearing its data may erase your entries. Export a backup regularly. The app does not add its own encryption to local storage; protect your device with a passcode.</p><a v-if="info==='privacy'" class="policy-link" href="./privacy.html" target="_blank" rel="noopener">Read the full privacy policy</a><p v-else>A simple diary for your thoughts, moods and everyday moments. Write, browse your calendar and save your favorites. No pressure, no rush. Just your own rhythm.</p></template><template v-if="artworkDialog"><span class="eyebrow">PERSONAL COLLECTION</span><h2>{{artworkTarget==='avatar'?'Your character':'Your story cover'}}</h2><p>Choose an illustration that feels like you.</p><div class="artwork-grid"><button v-for="art in artworks" :key="art.id" @click="chooseArtwork(art.id)" :aria-label="art.name"><img :src="artPath(art.id)" :alt="art.name" loading="lazy"/><span>{{art.name}}</span></button></div></template><template v-if="eraseDialog"><h2>Delete all your data?</h2><p>All entries, favorites and your profile will be removed from this device. Export a backup first if you want to keep them.</p><button class="primary full" @click="eraseAll">Delete all data</button><button class="text-button full" @click="eraseDialog=false">Cancel</button></template><template v-if="importDialog"><span class="eyebrow">BACKUP COPY</span><h2>Bring back your memories</h2><p>Choose a backup file or paste the JSON text saved using the system share menu. Existing entries will be kept.</p><button class="primary full" @click="pickImportFile">Choose a file</button><textarea class="backup-text" v-model="importText" placeholder="Paste your JSON backup" aria-label="Backup text"></textarea><button class="text-button full" :disabled="!importText.trim()" @click="importTextBackup">Restore from text</button></template><template v-if="deleteDialog"><h2>Delete this entry?</h2><p>You can only restore it from a previously exported backup.</p><button class="primary full" @click="deleteEntry">Delete entry</button><button class="text-button full" @click="deleteDialog=false">Keep entry</button></template><template v-if="discardDialog"><h2>Discard your changes?</h2><p>Your changes to this entry will be lost.</p><button class="primary full" @click="editor=false;discardDialog=false">Discard changes</button><button class="text-button full" @click="discardDialog=false">Keep writing</button></template></section></div>
  <div v-if="toast" class="toast" role="status">{{toast}}</div><input ref="importFile" type="file" accept="application/json,text/plain,.json,.txt" hidden @change="importEntries"/>
 </div>
</template>
<script>
import artworkList from './artworks.json';
import releaseConfig from './release-config.json';
const moodMigration={'Радость':'Happy','Спокойствие':'Calm','Энергия':'Energetic','Обычно':'Okay','Грусть':'Low'};
const normalizeEntry=e=>e&&Object.assign({},e,{mood:moodMigration[e.mood]||e.mood});
const legacyMonthNames={"\u044f\u043d\u0432\u0430\u0440\u044c": "January", "\u0444\u0435\u0432\u0440\u0430\u043b\u044c": "February", "\u043c\u0430\u0440\u0442": "March", "\u0430\u043f\u0440\u0435\u043b\u044c": "April", "\u043c\u0430\u0439": "May", "\u0438\u044e\u043d\u044c": "June", "\u0438\u044e\u043b\u044c": "July", "\u0430\u0432\u0433\u0443\u0441\u0442": "August", "\u0441\u0435\u043d\u0442\u044f\u0431\u0440\u044c": "September", "\u043e\u043a\u0442\u044f\u0431\u0440\u044c": "October", "\u043d\u043e\u044f\u0431\u0440\u044c": "November", "\u0434\u0435\u043a\u0430\u0431\u0440\u044c": "December"};
const key='original-diary-v1';
function nativeSavedState(){try{const b64=window.__DIARY_NATIVE_DATA_B64__;return b64?new TextDecoder().decode(Uint8Array.from(atob(b64),c=>c.charCodeAt(0))):null}catch(e){return null}}
function newestSavedState(local,native){if(!native)return local;if(!local)return native;try{return (JSON.parse(native).savedAt||0)>=(JSON.parse(local).savedAt||0)?native:local}catch(e){return local}}

const artPath=id=>'./artworks/'+(artworkList.some(a=>a.id===id)?id:'copper-muse')+'.webp';
function localDate(d=new Date()){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
const Icon={props:['name'],template:'<svg class="icon" aria-hidden="true"><use :href="\'#i-\'+name" /></svg>'};
const EntryCard={components:{Icon},props:['entry'],computed:{dateLabel(){return new Date(this.entry.date+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'long'})},image(){return artPath(this.entry.artworkId||'copper-muse')},face(){return {'Happy':'☀','Calm':'◡','Low':'☂','Energetic':'ϟ','Okay':'○'}[this.entry.mood]||'○'}},template:`<article class="entry-card card"><div class="entry-card-top"><span class="eyebrow">{{dateLabel}}</span><button class="icon-button" :class="{coral:entry.favorite}" :aria-label="entry.favorite?'Remove from favorites':'Add to favorites'" @click="$emit('favorite')"><icon name="heart"/></button></div><button class="entry-open" @click="$emit('open')"><div class="entry-layout"><div class="entry-art" :class="'tone-'+entry.mood"><img :src="image" alt="Entry illustration" loading="lazy"/><small>MY MOMENT</small></div><div class="entry-copy"><span class="eyebrow">{{entry.mood}}</span><h3>{{entry.title||'Untitled'}}</h3><p>{{entry.body}}</p></div></div><div class="entry-footer"><span>A moment kept</span><span>Read <icon name="arrow"/></span></div></button></article>`};
export default {name:'App',components:{Icon,EntryCard},data(){const now=new Date();return{artworks:artworkList,artworkDialog:false,artworkTarget:'entry',eraseDialog:false,heroIndex:0,heroTouch:0,tab:'home',tabs:[{id:'home',label:'Home',icon:'home'},{id:'entries',label:'Entries',icon:'book'},{id:'calendar',label:'Calendar',icon:'calendar'},{id:'favorites',label:'Favorites',icon:'heart'},{id:'profile',label:'Profile',icon:'user'}],entries:[],profile:{name:'',avatar:'tiger',since:now.toLocaleDateString('en-GB',{month:'long',year:'numeric'})},largeText:false,search:'',filterMood:'All',today:localDate(now),year:now.getFullYear(),month:now.getMonth(),calendarYear:now.getFullYear(),selectedDate:localDate(now),editor:false,draft:{title:'',body:'',date:localDate(now),mood:'Calm',favorite:false,artworkId:'copper-muse'},originalDraft:'',moods:[{label:'Happy',face:'☀'},{label:'Calm',face:'◡'},{label:'Energetic',face:'ϟ'},{label:'Okay',face:'○'},{label:'Low',face:'☂'}],moodDialog:false,profileDialog:false,settingsDialog:false,deleteDialog:false,discardDialog:false,info:'',importDialog:false,importText:'',nameDraft:'',toast:'',toastTimer:null}},computed:{heroArts(){return ['cobalt-groove','copper-muse','prism-pal'].map(id=>artworkList.find(a=>a.id===id))},heroArt(){return this.heroArts[this.heroIndex]},heroPrevious(){return this.heroArts[(this.heroIndex+2)%3]},heroNext(){return this.heroArts[(this.heroIndex+1)%3]},initial(){return(this.profile.name||'Me').charAt(0).toUpperCase()},tabTitle(){return this.tabs.find(t=>t.id===this.tab).label},todayLabel(){return new Date(this.today+'T12:00:00').toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long'}).toUpperCase()},sorted(){return this.entries.slice().sort((a,b)=>b.date.localeCompare(a.date)||b.updatedAt-a.updatedAt)},latest(){return this.sorted.slice(0,3)},visibleEntries(){const q=this.search.toLocaleLowerCase();return this.sorted.filter(e=>(this.tab!=='favorites'||e.favorite)&&(this.filterMood==='All'||e.mood===this.filterMood)&&(`${e.title} ${e.body}`).toLocaleLowerCase().includes(q))},favoritesCount(){return this.entries.filter(e=>e.favorite).length},activeDays(){return new Set(this.entries.map(e=>e.date)).size},monthLabel(){return new Date(this.calendarYear,this.month,1).toLocaleDateString('en-GB',{month:'long',year:'numeric'})},calendarDays(){let n=(new Date(this.calendarYear,this.month,1).getDay()+6)%7;return [...Array(n).fill(null),...Array.from({length:new Date(this.calendarYear,this.month+1,0).getDate()},(_,i)=>i+1)]},dayEntries(){return this.sorted.filter(e=>e.date===this.selectedDate)},wordCount(){return this.draft.body.trim()?this.draft.body.trim().split(/\s+/).length:0}},created(){try{const stored=newestSavedState(localStorage.getItem(key),nativeSavedState());if(stored){const s=JSON.parse(stored);if(Array.isArray(s.entries))s.entries=s.entries.map(normalizeEntry);if(!Array.isArray(s.entries)||!s.entries.every(this.validEntry))throw Error('invalid');this.entries=s.entries;this.profile=Object.assign(this.profile,s.profile||{});if(typeof this.profile.since==='string'){Object.entries(legacyMonthNames).forEach(([from,to])=>{this.profile.since=this.profile.since.replace(from,to)});this.profile.since=this.profile.since.replace(/\s+\u0433\.$/,'')}this.largeText=!!s.largeText}}catch(e){this.notify('Unable to read your saved data. Do not clear your device storage.')}},mounted(){this.nativeErrorHandler=event=>this.notify(event.detail||'Could not save the native backup. Keep your exported backup.');window.addEventListener('diary-native-error',this.nativeErrorHandler);this.nativeImportHandler=event=>{this.importText=event.detail;this.importTextBackup()};window.addEventListener('diary-native-import',this.nativeImportHandler);this.backHandler=()=>{if(this.editor)this.closeEditor();else if(this.moodDialog||this.profileDialog||this.settingsDialog||this.info)this.closeDialogs();else if(this.tab!=='home')this.tab='home';else if(window.plus)window.plus.runtime.quit()};this.readyHandler=()=>{if(window.plus)window.plus.key.addEventListener('backbutton',this.backHandler)};document.addEventListener('plusready',this.readyHandler);if(window.plus)this.readyHandler()},beforeDestroy(){window.removeEventListener('diary-native-error',this.nativeErrorHandler);window.removeEventListener('diary-native-import',this.nativeImportHandler);clearTimeout(this.toastTimer);document.removeEventListener('plusready',this.readyHandler);if(window.plus)window.plus.key.removeEventListener('backbutton',this.backHandler)},methods:{artPath,artName(id){return (artworkList.find(a=>a.id===id)||{}).name||'Copper Muse'},changeHero(delta){this.heroIndex=(this.heroIndex+delta+3)%3},swipeHero(event){const delta=event.changedTouches[0].clientX-this.heroTouch;if(Math.abs(delta)>35)this.changeHero(delta<0?1:-1)},chooseArtwork(id){if(this.artworkTarget==='avatar'){const next=Object.assign({},this.profile,{avatar:id});if(!this.persist(this.entries,next))return;this.profile=next}else this.$set(this.draft,'artworkId',id);this.artworkDialog=false},eraseAll(){const nextProfile={name:'',avatar:'tiger',since:new Date().toLocaleDateString('en-GB',{month:'long',year:'numeric'})};const oldLargeText=this.largeText;this.largeText=false;if(this.persist([],nextProfile)){this.entries=[];this.profile=nextProfile;this.eraseDialog=false;this.tab='home';this.notify('Your personal data has been deleted')}else this.largeText=oldLargeText},openSupport(){const url='mailto:'+releaseConfig.supportEmail;if(window.plus)window.plus.runtime.openURL(url);else location.href=url},validEntry(e){return e&&typeof e.id==='string'&&typeof e.title==='string'&&typeof e.body==='string'&&typeof e.date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(e.date)&&!isNaN(new Date(e.date+'T12:00:00').getTime())&&localDate(new Date(e.date+'T12:00:00'))===e.date&&e.title.length<=120&&e.body.length<=100000&&typeof e.mood==='string'&&['Happy','Calm','Energetic','Okay','Low'].includes(e.mood)&&typeof e.favorite==='boolean'&&Number.isFinite(e.updatedAt)},persist(entries=this.entries,profile=this.profile){try{const content=JSON.stringify({entries,profile,largeText:this.largeText,savedAt:Date.now()});localStorage.setItem(key,content);if(window.webkit&&window.webkit.messageHandlers&&window.webkit.messageHandlers.diary)window.webkit.messageHandlers.diary.postMessage({action:'save',content});return true}catch(e){this.notify('Unable to save. Check the available storage on your device.');return false}},persistPreferences(){this.persist()},notify(s){this.toast=s;clearTimeout(this.toastTimer);this.toastTimer=setTimeout(()=>this.toast='',4000)},switchTab(id){this.tab=id;this.search='';this.filterMood='All';window.scrollTo(0,0)},newEntry(date){this.draft={id:'',title:'',body:'',date:typeof date==='string'?date:localDate(),mood:'Calm',favorite:false,artworkId:this.heroArt.id};this.originalDraft=JSON.stringify(this.draft);this.editor=true;window.scrollTo(0,0)},openEntry(e){this.draft=Object.assign({},e);this.originalDraft=JSON.stringify(this.draft);this.editor=true;window.scrollTo(0,0)},closeEditor(){if(JSON.stringify(this.draft)!==this.originalDraft)this.discardDialog=true;else this.editor=false},saveEntry(){if(!this.draft.title.trim()&&!this.draft.body.trim())return this.notify('Add a title or a few words.');const e=Object.assign({},this.draft,{id:this.draft.id||Date.now().toString(36)+Math.random().toString(36).slice(2,9),title:this.draft.title.trim(),body:this.draft.body.trim(),updatedAt:Date.now()});if(!this.validEntry(e))return this.notify('Check the date and entry length (up to 100,000 characters).');const next=this.entries.filter(x=>x.id!==e.id).concat(e);if(this.persist(next)){this.entries=next;this.editor=false;this.notify('Your moment is saved')}},deleteEntry(){const next=this.entries.filter(e=>e.id!==this.draft.id);if(this.persist(next)){this.entries=next;this.deleteDialog=false;this.editor=false;this.notify('Entry deleted')}},toggleFavorite(e){const next=this.entries.map(x=>x.id===e.id?Object.assign({},x,{favorite:!x.favorite}):x);if(this.persist(next))this.entries=next},newMoodEntry(mood){this.moodDialog=false;this.newEntry();this.draft.mood=mood;this.originalDraft=JSON.stringify(this.draft)},closeDialogs(){this.moodDialog=this.profileDialog=this.settingsDialog=this.importDialog=this.artworkDialog=this.eraseDialog=this.deleteDialog=this.discardDialog=false;this.info=''},openSettings(){this.settingsDialog=true},saveProfile(){const p=Object.assign({},this.profile,{name:this.nameDraft.trim()});if(this.persist(this.entries,p)){this.profile=p;this.profileDialog=false}},formatDate(s){return new Date(s+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'long'})},dayKey(day){return localDate(new Date(this.calendarYear,this.month,day))},changeMonth(delta){let d=new Date(this.calendarYear,this.month+delta,1);this.month=d.getMonth();this.calendarYear=d.getFullYear()},hasDay(date){return this.entries.some(e=>e.date===date)},recordWord(n){return n===1?'entry':'entries'},exportEntries(){const text=JSON.stringify({format:'original-diary',version:1,exportedAt:new Date().toISOString(),entries:this.entries,profile:this.profile},null,2);const filename='diary-'+localDate()+'.json';if(window.webkit&&window.webkit.messageHandlers&&window.webkit.messageHandlers.diary){window.webkit.messageHandlers.diary.postMessage({action:'export',content:text,filename});return}if(window.plus){window.plus.io.requestFileSystem(window.plus.io.PRIVATE_DOC,fs=>fs.root.getFile(filename,{create:true},file=>file.createWriter(writer=>{writer.onerror=()=>this.notify('Could not write the backup');writer.onwrite=()=>{writer.onwrite=()=>{const path=file.toLocalURL();window.plus.share.sendWithSystem({type:'text',content:text},()=>this.notify('Your backup is ready'),()=>this.notify('Backup saved in the app documents'))};writer.seek(0);writer.write(text)};writer.truncate(0)},()=>this.notify('Could not write the file')),()=>this.notify('Could not create a file')),()=>this.notify('Storage is unavailable'));return}const url=URL.createObjectURL(new Blob([text],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);this.notify('Your backup is ready')},pickImportFile(){if(window.webkit&&window.webkit.messageHandlers&&window.webkit.messageHandlers.diary)window.webkit.messageHandlers.diary.postMessage({action:'import'});else this.$refs.importFile.click()},importTextBackup(){const text=this.importText;this.importEntries({target:{files:[{size:new Blob([text]).size,text:()=>Promise.resolve(text)}],value:''}})},async importEntries(event){const f=event.target.files[0];event.target.value='';if(!f)return;if(f.size>10*1024*1024)return this.notify('File too large: maximum 10 MB');try{const data=JSON.parse(await f.text());if(Array.isArray(data.entries))data.entries=data.entries.map(normalizeEntry);if(data.format!=='original-diary'||data.version!==1||!Array.isArray(data.entries)||!data.entries.every(this.validEntry))throw Error();const map=new Map(this.entries.map(e=>[e.id,e]));data.entries.forEach(e=>{const old=map.get(e.id);if(!old||e.updatedAt>old.updatedAt)map.set(e.id,e)});const next=Array.from(map.values());if(this.persist(next)){this.entries=next;this.importDialog=false;this.importText='';this.notify('Entries imported')}}catch(e){this.notify('Could not import: invalid backup format')}}}}
